const body = $json.body || $json;
const required = [
  ['event', body.event],
  ['recipient.email', body.recipient?.email],
  ['recipient.name', body.recipient?.name],
  ['signature.html', body.signature?.html],
  ['signature.text', body.signature?.text],
  ['signature.fileName', body.signature?.fileName],
];
const missing = required.filter(([, value]) => !value).map(([name]) => name);
if (body.event !== 'email_signature.send_requested') missing.push('event=email_signature.send_requested');
if (missing.length > 0) return [{ json: { ok: false, statusCode: 422, error: `Missing or invalid: ${missing.join(', ')}` } }];
return [{ json: { ok: true, statusCode: 200, event: body.event, metadata: body.metadata, recipient: body.recipient, signature: body.signature, subject: `Romega email signature for ${body.recipient.name}`, message: `${body.signature.html}<br><br><p>Attached is your generated Romega email signature package.</p>`, imageDataUrl: body.assets?.imageDataUrl || '' } }];
